import time
import datetime


def is_valid_argument(value, arguments):
    """
    Check if provided argument exist in list of possible arguments
    :param value: provided argument
    :param arguments: list of possible arguments
    :return True if argument is correct else raise InvalidArgument Error
    """
    if value not in arguments:
        raise InvalidArgument(value, arguments)
    else:
        return True


def is_valid_log_level(level):
    if level in ('TRACE', 'DEBUG', 'INFO', 'WARN', 'ERROR'):
        return True
    else:
        return False


def is_bytes(item):
    return isinstance(item, (bytes, bytearray))


# copied from Robot Framework
def time_to_seconds(time_to_reformat):
    time_to_reformat = time.strptime(time_to_reformat, '%H:%M:%S')
    time_in_seconds = datetime.timedelta(hours=time_to_reformat.tm_hour, minutes=time_to_reformat.tm_min,
                                         seconds=time_to_reformat.tm_sec).total_seconds()
    return time_in_seconds


class InvalidArgument(ValueError):
    """Raised if invalid argument is provided to function"""

    def __init__(self, value, arguments):
        ValueError.__init__(self)
        self.value = value
        self.arguments = arguments

    def __str__(self):
        msg = "Unknown value {}. Allowed arguments: {}".format(self.value, self.arguments)
        return msg
